const CACHE_PREFIX = 'weather_cache_';
const CACHE_TTL = 60 * 60 * 1000; // 1 hour

async function getWeather(city) {
  const key = CACHE_PREFIX + city;
  const cached = localStorage.getItem(key);

  if (cached) {
    const { data, timestamp } = JSON.parse(cached);
    if (Date.now() - timestamp < CACHE_TTL) {
      return data;
    }
  }

  const response = await fetch(
    `https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=YOUR_API_KEY`
  );
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const data = await response.json();

  localStorage.setItem(key, JSON.stringify({ data, timestamp: Date.now() }));
  return data;
}
```

This checks `localStorage` first, returns the cached data if it's under 1 hour old, and otherwise fetches from the API and stores the result with a timestamp. It uses no external libraries, and the 1-hour TTL reduces calls against your 1,000 daily limit.

Use a small dependency-free in-memory cache with a TTL (5 minutes), checked before each fetch:

```javascript
class WeatherCache {
  constructor(ttl = 300000) { // 5 minutes
    this.cache = {};
    this.ttl = ttl;
  }

  get(city) {
    if (this.cache[city] && this.cache[city].expires > Date.now()) {
      return this.cache[city].data;
    }
    return null;
  }

  set(city, data) {
    this.cache[city] = { data, expires: Date.now() + this.ttl };
  }
}

const cache = new WeatherCache();

async function fetchWeather(city) {
  const cached = cache.get(city);
  if (cached) return cached;

  try {
    const response = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=${process.env.OPENWEATHER_API_KEY}`);
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    const jsonData = await response.json();
    cache.set(city, jsonData);
    return jsonData;
  } catch (error) {
    console.error('Error fetching weather:', error);
    return null;
  }
}
```

This fits your constraints: no external libraries (app under 2.5MB), fewer calls against the 1,000/day limit, and the API key is read from `OPENWEATHER_API_KEY`. If you want the cache to persist across reloads, you can store the same structure in `localStorage` instead (5MB limit).

